DROP TABLE IF EXISTS `showtimes`;
SET @saved_cs_client     = @@character_set_client;
SET character_set_client = utf8;
CREATE TABLE `showtimes` (
  `id` bigint(20) unsigned NOT NULL auto_increment,
  `movie_id` bigint(20) unsigned NOT NULL,
  `screen_id` bigint(20) unsigned NOT NULL,
  `starts_at` datetime NOT NULL,
  `ends_at` datetime NOT NULL,
  `ticket_price` decimal(10,2) NOT NULL default '0.00',
  `status` enum('OPEN','CLOSED','CANCELLED') NOT NULL default 'OPEN',
  PRIMARY KEY  (`id`),
  KEY `movie_id` (`movie_id`),
  KEY `screen_id` (`screen_id`),
  KEY `idx_showtimes_start` (`starts_at`),
  CONSTRAINT `showtimes_ibfk_1` FOREIGN KEY (`movie_id`) REFERENCES `movies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `showtimes_ibfk_2` FOREIGN KEY (`screen_id`) REFERENCES `screens` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1212 DEFAULT CHARSET=latin1;
SET character_set_client = @saved_cs_client;

