INSERT INTO `ems_ai_document_chunks` VALUES (1,1,'Theo quy định Aurora Cinemas, khách hàng được đổi sang suất chiếu khác hoặc phim khác cùng giá vé trước ít nhất 60 phút so với giờ in trên vé. Vé đã qua giờ chiếu không hỗ trợ đổi hoặc hoàn.','{\"category\":\"NGHIEP-VU\"}','2026-10-06 06:53:12','2026-10-06 06:53:12'),(2,1,'Trường hợp suất chiếu bị gián đoạn do sự cố kỹ thuật (mất điện, lỗi máy chiếu, sự cố âm thanh trên 15 phút), nhân viên quầy vé có thẩm quyền hoàn tiền 100% hoặc cấp 01 Vé Xem Phim Miễn Phí (Complimentary Voucher) có thời hạn 30 ngày.','{\"category\":\"NGHIEP-VU\"}','2026-10-06 06:53:12','2026-10-06 06:53:12'),(3,1,'Đối với vé mua qua ứng dụng/online, khách hàng chỉ có thể hủy/đổi trên app trước 120 phút. Nếu đổi tại rạp, nhân viên đối chiếu mã OTP hoặc mã QR booking trên app.','{\"category\":\"NGHIEP-VU\"}','2026-10-06 06:53:12','2026-10-06 06:53:12'),(4,2,'Khi POS báo lỗi Giao dịch treo (#POS125 hoặc lỗi Timeout ngân hàng): Tuyệt đối không bấm thanh toán lại lần 2. Nhân viên chuyển sang tab Tra cứu giao dịch, kiểm tra mã tham chiếu POS Bank. Nếu tiền đã trừ khỏi tài khoản khách, bấm Xác nhận thành công thủ công.','{\"category\":\"POS\"}','2026-10-06 06:53:12','2026-10-06 06:53:12'),(5,2,'Quy trình phục vụ Concession 45 giây: Chào khách bằng nụ cười -> Xác nhận đơn bắp nước -> Up-sell combo VIP (chỉ thêm 19k nâng size bắp Lên Lớn) -> Quét thẻ thành viên -> Thanh toán -> Trao khay bắp nước bằng 2 tay kèm khăn giấy.','{\"category\":\"POS\"}','2026-10-06 06:53:12','2026-10-06 06:53:12'),(6,3,'Khi phòng chiếu chưa bắt đầu đúng giờ: Kiểm tra thứ tự: 1. Khóa bản quyền KDM (Key Delivery Message) đã nạp hợp lệ chưa. 2. Trạng thái bóng đèn Laser / Xenon trên máy chiếu. 3. Bản phim DCP đã ingest 100% vào server phụ chưa.','{\"category\":\"TMS\"}','2026-10-06 06:53:12','2026-10-06 06:53:12'),(7,3,'Nếu tín hiệu hình ảnh bị đen (Black Screen) lúc 00:00: Kỹ thuật viên chuyển sang nguồn dự phòng Channel 2 trên máy chiếu, khởi động lại bộ giải mã IMB trong 90 giây và thông báo Trưởng ca để phát loa xin lỗi khán giả.','{\"category\":\"TMS\"}','2026-10-06 06:53:12','2026-10-06 06:53:12'),(8,4,'Mô hình LAST khi xử lý khiếu nại khách hàng: L (Listen - Lắng nghe chân thành), A (Apologize - Xin lỗi vì trải nghiệm chưa trọn vẹn), S (Solve - Đưa ra giải pháp tức thì: đổi ghế, tặng bắp nước, bù vé), T (Thank - Cảm ơn khách đã góp ý để rạp cải thiện).','{\"category\":\"QUY-DINH\"}','2026-10-06 06:53:12','2026-10-06 06:53:12'),(9,4,'Phân loại độ tuổi phim theo Luật Điện Ảnh: P (Mọi lứa tuổi), K (Dưới 13 tuổi có phụ huynh đi kèm), T13 (Từ 13 tuổi trở lên), T16 (Từ 16 tuổi trở lên), T18 (Từ 18 tuổi trở lên), C (Cấm phổ biến). Nhân viên soát vé bắt buộc kiểm tra CCCD khi nghi vấn khách dưới tuổi quy định.','{\"category\":\"QUY-DINH\"}','2026-10-06 06:53:12','2026-10-06 06:53:12');
