INSERT INTO `ems_ai_documents` VALUES (1,'Quy trình đổi vé và hoàn tiền tại quầy POS','NGHIEP-VU',NULL,'1.0','active','Quy định đổi vé trước 60 phút trước giờ chiếu, hoàn voucher khi có sự cố kỹ thuật phòng chiếu.','2026-10-06 06:53:12','2026-10-06 06:53:12'),(2,'Sổ tay vận hành hệ thống bán vé POS & Quầy Concession','POS',NULL,'1.0','active','Hướng dẫn thao tác POS, quét barcode vé, in hóa đơn GTGT và xử lý lỗi treo giao diện.','2026-10-06 06:53:12','2026-10-06 06:53:12'),(3,'Quy trình xử lý sự cố hệ thống quản lý rạp TMS & Máy chiếu','TMS',NULL,'1.0','active','Xử lý lỗi KDM hết hạn, mất tín hiệu máy chiếu Christie/Barco và lỗi đồng bộ âm thanh Atmos.','2026-10-06 06:53:12','2026-10-06 06:53:12'),(4,'Nội quy và tiêu chuẩn 5 sao Aurora Hospitality','QUY-DINH',NULL,'1.0','active','Quy tắc tác phong nhân viên, trang phục, chào khách và xử lý tình huống LAST.','2026-10-06 06:53:12','2026-10-06 06:53:12');
